// Per-glyph clip boxes for the Pricedown overlay strokes, in em units relative
// to the pen position / baseline (y up). Index 0 is used for the outer
// gradient stroke, index 1 for the inner dark stroke. `cut` lists the box
// sides (l/r/t/b) where the stroke is hard-clipped flush; on the other sides
// the box is padded by a pixel. Characters without an entry are stroked as-is.
// Auto-generated from the original site's glyph data.

export type ClipSide = "" | "l" | "r" | "t" | "b" | "lr" | "bt";
export interface GlyphClipBox { x0: number; y0: number; x1: number; y1: number; cut: string }
export type GlyphClipTable = Record<string, readonly [GlyphClipBox, GlyphClipBox]>;

